head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF10000";
scwin.i = null;
scwin.v_str = null;
scwin.v_int_pay_mth = null;
scwin.v_int_set_std_int = null;
scwin.v_c_std_int = null;
scwin.v_rdmp_mth = null;
scwin.v_div_rdmp_cd = null;
scwin.v_str1 = null;
scwin.v_str2 = null;
scwin.v_flag = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — flag, bndMktactTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.v_str = '' + dma_result.get("curr_tp_cd") + '';
        scwin.v_int_pay_mth = '' + dma_result.get("int_pay_methd_cd") + '';
        scwin.v_int_set_std_int = '' + dma_result.get("intRtDecsnMiscBasIntNm") + '';
        scwin.v_c_std_int = '' + dma_result.get("coupnRtDecsnBasIntCd") + '';
        scwin.v_rdmp_mth = '' + dma_result.get("redmpt_methd_tp_cd") + '';
        scwin.v_div_rdmp_cd = '' + dma_result.get("splitRedmptTpCd") + '';
        scwin.v_str1 = '' + dma_result.get("regInstCd") + '';
        scwin.v_str2 = '' + dma_result.get("regInstNm") + '';
        scwin.v_flag = String(((dma_pageContext.get("flag") ?? "")) == null ? '' : ((dma_pageContext.get("flag") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("flag") ?? "")) == null ? '' : ((dma_pageContext.get("flag") ?? "")));
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_datefmt_cal_fstIntPayDd();
        scwin.init_datefmt_cal_saleDd();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf10000.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "ipt_cfiCd", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'GB'); } }, { id: "ipt_cfiCd_2", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "ipt_cfiCd_3", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'AB'); } }, { id: "c_when_194", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_otherwise_196", fn: function(){ return (!((String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'))); } }, { id: "c_when_201", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_when_294", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_otherwise_307", fn: function(){ return (!((String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_bndMktactTpCd", fn: function () { return String(String((dma_pageContext.get("bndMktactTpCd") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_fstIntPayDd
 * @description 초기화 — datefmt cal fst Int Pay Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_fstIntPayDd = function () { $c.date.checkCalendarFormat("cal_fstIntPayDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_saleDd
 * @description 초기화 — datefmt cal sale Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_saleDd = function () { $c.date.checkCalendarFormat("cal_saleDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const header_cd = $c.util.getComponent('ipt_bndMktactTpCd').getValue();
        if (header_cd === '112') {
            dmenus = { "bmenu": 1, "mmenu": 9 };
        } else {
            if (header_cd === '122') {
                dmenus = { "bmenu": 1, "mmenu": 9 };
            } else {
                if (header_cd === '132') {
                    dmenus = { "bmenu": 1, "mmenu": 9 };
                } else {
                    if (header_cd === '142') {
                        dmenus = { "bmenu": 1, "mmenu": 9 };
                    } else {
                        if (header_cd === '301') {
                            dmenus = { "bmenu": 1, "mmenu": 9 };
                        }
                    }
                }
            }
        }
        $('div#header').trigger('mouseleave');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf10000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(>- vs bloclisting) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf10000.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf10000.btn_mpd_files_del_onclick' }); }
};

