/**
 * @method
 * @name clickCreditValuInstCd
 * @description click Credit Valu Inst Cd 처리
 * @param {*} inst_cd inst_cd
 * @param {*} type type
 * @param {*} frm frm
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.clickCreditValuInstCd = function (inst_cd, type, frm, obj) {
    if (obj.checked) {
        $c.util.getComponent("frm.credit_valu_inst_cd" + type).setValue(inst_cd);
        frm["byinst_credit_valu_grd" + type].disabled = false;
        frm["sf_valu_yn" + type].disabled = true;
    } else {
        $c.util.getComponent("frm.credit_valu_inst_cd" + type).setValue('');
        $c.util.getComponent("frm.byinst_credit_valu_grd" + type).setValue('');
        frm["byinst_credit_valu_grd" + type].disabled = true;
        $c.util.getComponent("frm.sf_valu_yn" + type).checked = false;
        frm["sf_valu_yn" + type].disabled = true;
    }
};

/**
 * @method
 * @name TempSaveCheckValues
 * @description Temp Save Check Values 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.TempSaveCheckValues = async function () {
    let str_iss_mth = '';
    for (scwin.i = 0; scwin.i < 3; scwin.i++) {
        if ((String($c.util.getComponent(["ipt_ckBndIsuMethdCd", "ipt_ckBndIsuMethdCd_2", "ipt_ckBndIsuMethdCd_3", "ipt_ckBndIsuMethdCd_4", "ipt_ckBndIsuMethdCd_5", "ipt_ckBndIsuMethdCd_6"][scwin.i]).getValue() || '') !== '') === true) {
            $c.util.getComponent(["ipt_ckBndIsuMethdCd", "ipt_ckBndIsuMethdCd_2", "ipt_ckBndIsuMethdCd_3", "ipt_ckBndIsuMethdCd_4", "ipt_ckBndIsuMethdCd_5", "ipt_ckBndIsuMethdCd_6"][scwin.i]).setValue(1);
        } else {
            $c.util.getComponent(["ipt_ckBndIsuMethdCd", "ipt_ckBndIsuMethdCd_2", "ipt_ckBndIsuMethdCd_3", "ipt_ckBndIsuMethdCd_4", "ipt_ckBndIsuMethdCd_5", "ipt_ckBndIsuMethdCd_6"][scwin.i]).setValue(0);
        }
        str_iss_mth += $c.util.getComponent(["ipt_ckBndIsuMethdCd", "ipt_ckBndIsuMethdCd_2", "ipt_ckBndIsuMethdCd_3", "ipt_ckBndIsuMethdCd_4", "ipt_ckBndIsuMethdCd_5", "ipt_ckBndIsuMethdCd_6"][scwin.i]).getValue();
    }
    $c.util.getComponent('dma_TempSaveCheckValuesReq').set('bndIsuMethdCd', str_iss_mth);
    $c.util.getComponent('dma_TempSaveCheckValuesReq').set('method', "requestBlocListing");
    await scwin.tx_TempSaveCheckValues();
};

/**
