 */
scwin.CheckValues = async function (mkt_cd) {
    let nullChk = 'OK';
    isu_nm = new Array(12);
    for (idx = 0; idx < 12; idx++) {
        isu_nm[idx] = (console.warn("[sdd] unresolved:dmap-member:" + "appl_isu_nm @ dma_TempSaveCheckValuesReq.applIsuNm"), $c.util.getComponent('dma_TempSaveCheckValuesReq'))[idx].value;
        if ($c.str.getByteLength(isu_nm[idx]) > 0) {
