    if (nullChk === 'OK') {
        await $c.win.alert("월별발행계획 상세내역입력 버튼을 선택하셔서 \n\r월별종목내역을 입력하십시오.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    } else {
        BulkLstCheckValues(mkt_cd);
